static const NPI_MODULEID *ip_module_id( USHORT family )
{
    if (family == AF_INET) return &NPI_MS_IPV4_MODULEID;
    if (family == AF_INET6) return &NPI_MS_IPV6_MODULEID;
    return NULL;
}
